const previo = $('When Executed by Another Workflow').first().json;
const m = previo.mensaje.toLowerCase();
const alias = {
  'Levstamp': /levstamp|aptis|british council/,
  'Tu Home Office': /tu home office|home office|afiliados amazon|amazon afiliados/,
  'Wedding Planner Pro': /wedding planner|nuptial|boda|novios/,
  'JARVIS': /\bjarvis\b/
};
let nombre_proyecto = '';
for (const [nombre, patron] of Object.entries(alias)) {
  if (patron.test(m)) { nombre_proyecto = nombre; break; }
}
return [{ json: { usuario_id: previo.usuario_id, chat_id: previo.chat_id, mensaje: previo.mensaje, nombre_proyecto } }];

const previo = $('Detectar por palabra clave').first().json;
const fila = $json;
const atributos = fila.atributos || {};
const pendientes = Array.isArray(atributos.pendientes_nuevos) ? atributos.pendientes_nuevos : [];
const listaPendientes = pendientes.length ? pendientes.map((p, i) => `${i}. ${p.nota || p}`).join('
') : '(no hay pendientes guardados todavia)';

const prompt = `Mensaje del usuario sobre el proyecto "${previo.nombre_proyecto}":
"${previo.mensaje}"

Lista actual de pendientes guardados de este proyecto, numerada:
${listaPendientes}

Decide UNA de estas tres acciones:
- "completar": si el mensaje dice que algo YA SE HIZO o se completo. Esto aplica tanto si corresponde a un pendiente de la lista como si es un avance que nunca estuvo apuntado como pendiente. Si corresponde EXACTAMENTE a un pendiente de la lista, indica su NUMERO en indice_completado. Si no corresponde a ninguno de la lista pero igualmente es algo ya hecho, deja indice_completado en null (se registrara igual como completado, no hace falta que estuviera en la lista).
- "agregar": si el mensaje propone algo nuevo que falta hacer (todavia no hecho), no relacionado con completar nada.
- "preguntar": solo si el mensaje es realmente ambiguo y no se puede saber si es algo hecho o algo pendiente nuevo.

Responde SOLO un objeto JSON, sin markdown, con esta forma exacta:
{"accion":"completar|agregar|preguntar","indice_completado":<numero o null>,"nota":"<texto breve para guardar, si accion es completar o agregar>","pregunta":"<pregunta breve si accion es preguntar>"}`;

return [{ json: { usuario_id: previo.usuario_id, chat_id: previo.chat_id, mensaje: previo.mensaje, nombre_proyecto: previo.nombre_proyecto, id_viejo: fila.id, raiz_id: fila.raiz_id, version_vieja: fila.version, atributos_viejo: atributos, prompt } }];

const previo = $('Armar prompt Claude').first().json;
const raw = $json.stdout ?? '';
let texto = raw;
try {
  const parsed = JSON.parse(raw);
  texto = parsed.result ?? parsed.text ?? parsed.response ?? parsed.output ?? raw;
} catch (e) {}
let decision = { accion: 'agregar', nota: previo.mensaje || 'No he entendido bien el cambio' };
try {
  const match = String(texto).match(/\{[\s\S]*\}/);
  if (match) decision = JSON.parse(match[0]);
} catch (e) {}
return [{ json: { ...previo, decision } }];

const previo = $json;
const decision = previo.decision;
const atributosViejo = previo.atributos_viejo || {};
let pendientes = Array.isArray(atributosViejo.pendientes_nuevos) ? [...atributosViejo.pendientes_nuevos] : [];
let actualizaciones = Array.isArray(atributosViejo.actualizaciones) ? [...atributosViejo.actualizaciones] : [];
const hoy = new Date().toISOString().slice(0,10);
let mensajeFinal = '';

if (decision.accion === 'completar') {
  let notaCompletada = decision.nota;
  const tieneIndice = decision.indice_completado !== null && decision.indice_completado !== undefined && pendientes[decision.indice_completado];
  if (tieneIndice) {
    const quitado = pendientes[decision.indice_completado];
    pendientes = pendientes.filter((_, i) => i !== decision.indice_completado);
    notaCompletada = decision.nota || quitado.nota || quitado;
  }
  if (!notaCompletada) notaCompletada = previo.mensaje;
  actualizaciones.push({ fecha: hoy, nota: notaCompletada });
  mensajeFinal = `Marcado como hecho en "${previo.nombre_proyecto}": ${notaCompletada}`;
} else if (decision.accion === 'agregar') {
  pendientes.push({ fecha: hoy, nota: decision.nota });
  mensajeFinal = `Anotado como pendiente en "${previo.nombre_proyecto}": ${decision.nota}`;
} else {
  mensajeFinal = decision.pregunta || 'No he entendido bien el cambio, ¿puedes aclararlo?';
}

const atributosNuevo = { ...atributosViejo, pendientes_nuevos: pendientes, actualizaciones };

return [{ json: { ...previo, accion: decision.accion, atributos_nuevo: JSON.stringify(atributosNuevo), mensaje_final: mensajeFinal } }];
